CREATE TABLE study_plans (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, daily_available_minutes INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_plan_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_plan_student(student_id));
CREATE TABLE study_tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, plan_id BIGINT NULL, title VARCHAR(255) NOT NULL, subject VARCHAR(120) NULL, scheduled_date DATE NULL, estimated_minutes INT NOT NULL, priority VARCHAR(12) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(16) NOT NULL DEFAULT 'PENDING', completed_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_task_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_task_plan FOREIGN KEY(plan_id) REFERENCES study_plans(id) ON DELETE SET NULL, INDEX idx_task_student_status(student_id,status), INDEX idx_task_date(student_id,scheduled_date));
